metadata.orrery:spec:
title: Any YouTube video in, sheet music and tab out
subtitle: Default routes; each stem's model can be changed with STEMDECK_TRANSCRIBE_<STEM>
direction: down
theme: dark
skin: stage

story: [youtube, fetch, demucs, stems, mt3, rawNotes, quantize, alphatex, notation]

groups:
  input: { type: zone, label: Input }
  import: { type: zone, label: Import pipeline (every song) }
  worker: { type: zone, label: Worker (on demand) }
  notesFolder: { type: zone, label: Song folder (transcription/) }
  perRequest: { type: zone, label: "Server, per request (not stored)" }
  browser: { type: zone, label: Browser }

nodes:
  youtube: { icon: logos:youtube-icon, label: YouTube or SoundCloud link, in: input }
  upload: { icon: tabler:file-music, label: "Audio file (MP3, WAV, FLAC...)", in: input, align: youtube }
  fetch: { icon: tabler:download, label: "Download + decode (yt-dlp, ffmpeg)", in: input }
  demucs: { icon: tabler:arrows-split, label: Demucs htdemucs_6s, in: import }
  stems: { icon: tabler:waveform, label: Six stems, note: "stems/: vocals drums bass guitar piano other", in: import }
  beatgrid: { icon: tabler:metronome, label: Beat tracking (beat_this), in: import }
  vocalSplit: { icon: tabler:microphone, label: Vocal split (UVR Karaoke 2), note: optional, in: import }
  extraVocals: { icon: tabler:microphone-2, label: Lead and backing vocals, note: stems/, in: import }
  beatFiles: { icon: tabler:json, label: Beat grid (beats.json), note: your edits win, in: import }
  crepe: { icon: tabler:wave-sine, label: CREPE + pitch-to-notes, note: "vocals, lead vocals, bass", in: worker }
  piano: { icon: tabler:piano, label: ByteDance piano model, note: piano, in: worker }
  mt3: { icon: tabler:brain, label: YourMT3+, note: "guitar, other, backing, drums", in: worker }
  rawNotes: { icon: tabler:json, label: Raw notes per stem, note: "<stem>.json", in: notesFolder }
  quantize: { icon: tabler:grid-dots, label: Quantise on beat grid, in: perRequest }
  fingering: { icon: tabler:hand-finger, label: "Fingering (guitar, bass)", in: perRequest }
  midi: { icon: tabler:file-music, label: MIDI file, in: perRequest }
  musicxml: { icon: tabler:file-type-xml, label: MusicXML score, in: perRequest }
  alphatex: { icon: tabler:music, label: alphaTex score, in: perRequest }
  notation: { icon: ph:music-note, label: Notation view (alphaTab), in: browser }
  guitarPro: { icon: tabler:file-download, label: Guitar Pro file, in: browser, align: notation }
  viz: { icon: logos:threejs, label: Visualizers (Three.js), in: browser }

edges:
  - youtube -> fetch: link
  - upload -> fetch: file
  - fetch -> demucs: audio
  - demucs -> stems: 6 stems
  - stems -> beatgrid: drums stem
  - beatgrid -> beatFiles: beat times
  - stems -> vocalSplit: vocals (optional)
  - vocalSplit -> extraVocals: lead + backing
  - stems -> crepe: "vocals, bass"
  - extraVocals -> crepe: lead vocals
  - stems -> piano: piano
  - stems -> mt3: "guitar, other, drums"
  - extraVocals -> mt3: backing vocals
  - crepe -> rawNotes: notes
  - piano -> rawNotes: "notes, velocities"
  - mt3 -> rawNotes: notes; drums as GM keys
  - rawNotes -> quantize: notes
  - beatFiles -> quantize: beat grid
  - rawNotes -> midi: as played
  - quantize -> midi: quantised
  - quantize -> fingering: "guitar, bass"
  - quantize -> musicxml: bars
  - fingering -> musicxml: tab staves
  - quantize -> alphatex: bars
  - fingering -> alphatex: "strings, frets"
  - alphatex -> notation: score
  - notation -> guitarPro: exports
  - rawNotes -> viz: notes as played
  - beatFiles -> viz: "beats, bars"
